import{_ as o,o as d,c as t,a3 as a}from"./chunks/framework.BlnmUGcd.js";const f=JSON.parse('{"title":"LFOs","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/lfos.md","filePath":"developers/commands/lfos.md"}'),c={name:"developers/commands/lfos.md"};function s(n,e,r,i,l,p){return d(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="lfos" tabindex="-1">LFOs <a class="header-anchor" href="#lfos" aria-label="Permalink to &quot;LFOs&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; lfo cfg get s32 3</span></span>
<span class="line"><span>s32&gt; lfo cfg set s32 3 wave=sine freq=3.75 enabled=on</span></span>
<span class="line"><span>s32&gt; macro set 5 2 mode=cc msb=1</span></span>
<span class="line"><span>s32&gt; lfo assign add 3 target=macro pot=5 macro=2 min=-0.25 max=0.25</span></span>
<span class="line"><span>s32&gt; lfo assign list</span></span>
<span class="line"><span>s32&gt; lfo assign remove 1</span></span></code></pre></div><p>A macro whose mode takes no LFO (disabled, device, rack control, S32 LFO) is refused with <code>BadRequest</code>; set a MIDI-message mode first.</p><p><code>DOMAIN</code> is <code>s32</code> (the S32&#39;s own <a href="/versions/cli/v2.1.0/lfos/">LFOs</a>). <code>INDEX</code> is the LFO, <code>1</code>–<code>16</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><code>lfo cfg get DOMAIN INDEX</code> prints the LFO&#39;s settings (<code>retrigger=</code> included), then its IN SNAPSHOT (<code>liveOwned=</code>) and ALLOW MORPH (<code>allowMorph=</code>) bits as hex masks. A stored reserved retrigger value prints <code>reserved(N)</code>. <code>lfo cfg set</code> never changes those bits. Use <a href="./snapshots#in-snapshot"><code>snapshot flags</code> and <code>snapshot parent</code></a>.</p><p><code>lfo cfg set DOMAIN INDEX key=value …</code> changes only the keys you name; there is no positional frequency form. <code>freq=HZ</code> sets the frequency and leaves <code>enabled</code> alone. Values outside the LFO&#39;s range are refused.</p><table tabindex="0"><thead><tr><th>Key</th><th>S32</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>on</code> / <code>off</code></td></tr><tr><td><code>wave</code></td><td>see below</td></tr><tr><td><code>freq</code></td><td>Hz</td></tr><tr><td><code>bpm</code></td><td>Clock division, used with <code>sync=on</code></td></tr><tr><td><code>sync</code></td><td><code>on</code> / <code>off</code></td></tr><tr><td><code>retrigger</code></td><td><code>off</code> / <code>enable</code> / <code>start</code> / <code>both</code> (default <code>start</code>)</td></tr><tr><td><code>phase</code></td><td>Degrees</td></tr><tr><td><code>offset</code></td><td>yes</td></tr><tr><td><code>amp</code></td><td><code>0</code>–<code>1</code></td></tr><tr><td><code>min</code> / <code>max</code></td><td>yes</td></tr></tbody></table><p>Waves: <code>sine</code>, <code>triangle</code>, <code>square</code>, <code>saw</code>, <code>fold</code>, <code>s-h</code>, <code>exponential</code>, <code>stepped</code>, <code>double-sine</code>, <code>rev-saw</code>, <code>bell</code>, <code>double-triangle</code>, <code>smooth-random</code>, <code>trapezoid</code>, <code>pump</code>, <code>rounded-square</code>, <code>half-sine</code>.</p><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h2><p><code>lfo assign add LFO target=… …</code> adds a row. <code>lfo assign set ROW LFO target=… …</code> rewrites one. <code>lfo assign remove ROW</code> deletes one. <code>lfo assign list</code> shows the row numbers.</p><table tabindex="0"><thead><tr><th><code>target=</code></th><th>Moves</th><th>Address</th><th><code>param=</code></th></tr></thead><tbody><tr><td><code>device</code></td><td>A rack device parameter</td><td><code>rack=ID device=ID</code> (ids from <code>rack list</code> / <code>device list</code>)</td><td>Parameter name (<code>bypass</code>, <code>rate</code>, <code>gate</code>, …) or number</td></tr><tr><td><code>lfo</code></td><td>Another LFO in the same domain</td><td><code>targetLfo=LFO</code> (<code>1</code>–<code>16</code>)</td><td>LFO parameter (<code>enabled</code>, <code>wave</code>, <code>rate</code>, <code>sync</code>, <code>depth</code>, <code>offset</code>, <code>phase</code>)</td></tr><tr><td><code>macro</code></td><td>A knob macro</td><td><code>pot=KNOB macro=MACRO</code></td><td>—</td></tr></tbody></table><p>An LFO can&#39;t modulate itself or close a loop of LFOs (1 → 2 → 1). Those rows are refused.</p><p>A rack, device or parameter that is not in the project exits <code>4</code> (<code>NotFound</code>) and changes nothing. Use the ids from <code>rack list</code> / <code>device list</code>, not positions, and a parameter that device has in <code>schema</code>.</p><h3 id="range" tabindex="-1">Range <a class="header-anchor" href="#range" aria-label="Permalink to &quot;Range&quot;">​</a></h3><p>For <code>device</code> and <code>lfo</code> targets, <code>min</code> and <code>max</code> are values in the target&#39;s own range. Values outside it are clamped to the edge. On S32 targets <code>min</code> above <code>max</code> runs the sweep the other way.</p><p>A time that changes with SYNC (Delay <code>delay-time</code>, Arpeggiator <code>rate</code>, Envelope <code>attack</code> / <code>hold</code> / <code>decay</code> / <code>release</code>) is the exception: <code>min</code> and <code>max</code> are positions from <code>0</code> to <code>1</code> of the range it has in its current mode, so the row keeps working when SYNC changes. <code>lfo assign list</code> prints them that way (<code>range=0.250..0.750</code>). A value above <code>1</code> is read in the current unit (ticks or ms) and stored as its position: <code>min=6 max=96</code> on a SYNCED Arpeggiator is <code>1/16</code> … <code>1/1</code>.</p><p>For <code>macro</code> targets, <code>min</code> and <code>max</code> are the BELOW and ABOVE window around the knob, as fractions of the macro&#39;s range from <code>-1</code> to <code>1</code>. The default is <code>-0.5</code> / <code>0.5</code>. <code>min=0 max=0.4</code> only rises above the knob. Protocol 5 (<code>hello</code> shows it) uses this window, and so does capability bit <code>1024</code> on protocol 4.</p><h2 id="output-after-a-set" tabindex="-1">Output after a set <a class="header-anchor" href="#output-after-a-set" aria-label="Permalink to &quot;Output after a set&quot;">​</a></h2><p><code>lfo cfg set</code> prints the LFO&#39;s settings after its confirmation, and <code>lfo assign add</code> and <code>lfo assign set</code> print the row they wrote, with no list header (<a href="./session#a-set-prints-the-state-it-left">A set prints the state it left</a>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ s32 --loopback lfo cfg set s32 1 freq=2 wave=triangle</span></span>
<span class="line"><span>lfo s32 1 updated</span></span>
<span class="line"><span>s32 lfo 1: enabled=on wave=triangle freq=2.000 bpm=1.000 amp=1.000 offset=0.000 sync=on retrigger=start liveOwned=0x0000 allowMorph=0x9000</span></span>
<span class="line"><span>$ s32 --loopback lfo assign add 1 target=macro pot=2 macro=1</span></span>
<span class="line"><span>added assignment 1 (1 total)</span></span>
<span class="line"><span>  [1] lfo=1 target=macro pot=2 macro=1 range=-0.500..0.500</span></span></code></pre></div><p>With <code>--json</code>, <code>lfo cfg get</code> also reports <code>phase</code> in degrees (<code>0</code>–<code>360</code>, as <code>phase=</code> takes it); the text output does not print it. <code>amp</code> is <code>null</code> for a CV LFO and <code>depth</code> is <code>null</code> for an s32 LFO. In <code>lfo assign list --json</code> each row has <code>rack</code>, <code>device</code>, <code>param</code>, <code>pot</code>, <code>macro</code> and <code>targetLfo</code>, <code>null</code> where the target does not use them, and <code>range=a..b</code> is <code>min</code> and <code>max</code>.</p>`,22)])])}const g=o(c,[["render",s]]);export{f as __pageData,g as default};
